 "content": "from collections import Counter

def transform(grid):
    """Find every translation of the marked motif whose marked cells are all 0,
    and recolor those cells with the motif's color."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = next((v for v, n in counts.most_common() if v not in (0, background)), None)
    if marker is None:
        return [row[:] for row in grid]
    motif = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    r0, c0 = min(r for r, c in motif), min(c for r, c in motif)
    motif = [(r-r0, c-c0) for r, c in motif]
    mh, mw = max(r for r, c in motif)+1, max(c for r, c in motif)+1
    out = [row[:] for row in grid]
    for top in range(h-mh+1):
        for left in range(w-mw+1):
            if all(grid[top+r][left+c] == 0 for r, c in motif):
                for r, c in motif:
                    out[top+r][left+c] = marker
    return out
